package aggregate

import (
	"context"
	"math"
	"sort"
	"testing"

	"github.com/steamwo/fssql/internal/core/memory"
	"github.com/steamwo/fssql/internal/core/types"
	"github.com/steamwo/fssql/internal/core/vector"
)

func aggEnv(limit int64) (*memory.Manager, *memory.Scope, *memory.BufferManager) { mm:=memory.NewManager(limit); scope:=mm.NewScope(); return mm,scope,memory.NewBufferManager(nil) }
func makeBigIntChunk(t testing.TB,scope *memory.Scope,bm *memory.BufferManager,groups,vals []int64,nullValue map[int]bool)*vector.DataChunk{t.Helper();gv,err:=vector.NewFlat(scope,bm,types.LogicalType{ID:types.BigInt},len(groups));if err!=nil{t.Fatal(err)};vv,err:=vector.NewFlat(scope,bm,types.LogicalType{ID:types.BigInt},len(vals));if err!=nil{gv.Release();t.Fatal(err)};for i,x:=range groups{gv.SetInt64(i,x)};for i,x:=range vals{if nullValue!=nil&&nullValue[i]{vv.SetNull(i)}else{vv.SetInt64(i,x)}};c,err:=vector.NewDataChunk(gv,vv);if err!=nil{gv.Release();vv.Release();t.Fatal(err)};return c}
func TestBindDuckDBIntegerSumHugeInt(t *testing.T){for _,id:=range []types.LogicalTypeID{types.TinyInt,types.SmallInt,types.Integer,types.BigInt}{got,err:=Bind([]types.LogicalType{{ID:id}},[]Spec{{Kind:Sum,Input:0}});if err!=nil{t.Fatal(err)};if got[0].OutputType.ID!=types.HugeInt||got[0].OutputType.Physical()!=types.PhysicalInt128{t.Fatalf("SUM(%v) output=%+v",id,got[0].OutputType)}};got,err:=Bind([]types.LogicalType{{ID:types.BigInt}},[]Spec{{Kind:Avg,Input:0},{Kind:CountStar}});if err!=nil{t.Fatal(err)};if got[0].OutputType.ID!=types.Double||got[1].OutputType.ID!=types.BigInt{t.Fatalf("AVG/COUNT binding=%+v",got)}}
func TestHashAggregateGroupedCoreFunctions(t *testing.T){mm,scope,bm:=aggEnv(8<<20);a,err:=NewHashAggregate(scope,bm,[]types.LogicalType{{ID:types.BigInt},{ID:types.BigInt}},[]int{0},[]Spec{{Kind:CountStar},{Kind:Count,Input:1},{Kind:Sum,Input:1},{Kind:Avg,Input:1},{Kind:Min,Input:1},{Kind:Max,Input:1}},4);if err!=nil{t.Fatal(err)};c:=makeBigIntChunk(t,scope,bm,[]int64{2,1,2,1,1},[]int64{10,20,30,40,50},map[int]bool{3:true});if err:=a.Consume(context.Background(),c);err!=nil{t.Fatal(err)};c.Release();out,err:=a.Finalize(context.Background());if err!=nil{t.Fatal(err)};type row struct{g,countStar,count,min,max int64;sum types.Int128;avg float64};rows:=make([]row,out.Cardinality);for i:=range rows{rows[i].g,_=out.Columns[0].Int64(i);rows[i].countStar,_=out.Columns[1].Int64(i);rows[i].count,_=out.Columns[2].Int64(i);rows[i].sum,_=out.Columns[3].Int128(i);rows[i].avg,_=out.Columns[4].Float64(i);rows[i].min,_=out.Columns[5].Int64(i);rows[i].max,_=out.Columns[6].Int64(i)};sort.Slice(rows,func(i,j int)bool{return rows[i].g<rows[j].g});if rows[0].g!=1||rows[0].countStar!=3||rows[0].count!=2||rows[0].sum!=types.Int128FromInt64(70)||rows[0].avg!=35||rows[0].min!=20||rows[0].max!=50{t.Fatalf("group1=%+v",rows[0])};if rows[1].g!=2||rows[1].countStar!=2||rows[1].count!=2||rows[1].sum!=types.Int128FromInt64(40)||rows[1].avg!=20||rows[1].min!=10||rows[1].max!=30{t.Fatalf("group2=%+v",rows[1])};out.Release();a.Release();if err:=scope.Close();err!=nil{t.Fatal(err)};if mm.Used()!=0{t.Fatalf("memory leak=%d",mm.Used())}}
func TestHashAggregateSumExceedsInt64(t *testing.T){mm,scope,bm:=aggEnv(1<<20);a,err:=NewHashAggregate(scope,bm,[]types.LogicalType{{ID:types.BigInt}},nil,[]Spec{{Kind:Sum,Input:0}},1);if err!=nil{t.Fatal(err)};v,_:=vector.NewFlat(scope,bm,types.LogicalType{ID:types.BigInt},2);v.SetInt64(0,math.MaxInt64);v.SetInt64(1,1);c,_:=vector.NewDataChunk(v);if err:=a.Consume(context.Background(),c);err!=nil{t.Fatal(err)};c.Release();out,err:=a.Finalize(context.Background());if err!=nil{t.Fatal(err)};if out.Columns[0].Type.ID!=types.HugeInt{t.Fatalf("type=%v",out.Columns[0].Type.ID)};got,ok:=out.Columns[0].Int128(0);want:=types.Int128{Lo:1<<63,Hi:0};if !ok||got!=want{t.Fatalf("sum=%+v ok=%v",got,ok)};out.Release();a.Release();if err:=scope.Close();err!=nil{t.Fatal(err)};if mm.Used()!=0{t.Fatalf("memory leak=%d",mm.Used())}}
func TestHashAggregateEmptyAndNullSemantics(t *testing.T){mm,scope,bm:=aggEnv(1<<20);a,err:=NewHashAggregate(scope,bm,[]types.LogicalType{{ID:types.BigInt}},nil,[]Spec{{Kind:CountStar},{Kind:Count,Input:0},{Kind:Sum,Input:0},{Kind:Avg,Input:0},{Kind:Min,Input:0},{Kind:Max,Input:0}},1);if err!=nil{t.Fatal(err)};out,err:=a.Finalize(context.Background());if err!=nil{t.Fatal(err)};for _,col:=range []int{0,1}{if v,ok:=out.Columns[col].Int64(0);!ok||v!=0{t.Fatalf("count=%d,%v",v,ok)}};for _,col:=range []int{2,3,4,5}{if out.Columns[col].IsValid(0){t.Fatalf("col %d not NULL",col)}};out.Release();a.Release();b,_:=NewHashAggregate(scope,bm,[]types.LogicalType{{ID:types.BigInt}},nil,[]Spec{{Kind:Count,Input:0},{Kind:Sum,Input:0}},1);v,_:=vector.NewFlat(scope,bm,types.LogicalType{ID:types.BigInt},2);v.SetNull(0);v.SetNull(1);c,_:=vector.NewDataChunk(v);if err:=b.Consume(context.Background(),c);err!=nil{t.Fatal(err)};c.Release();out,err=b.Finalize(context.Background());if err!=nil{t.Fatal(err)};if x,ok:=out.Columns[0].Int64(0);!ok||x!=0{t.Fatalf("count null=%d,%v",x,ok)};if out.Columns[1].IsValid(0){t.Fatal("sum null-only should be NULL")};out.Release();b.Release();if err:=scope.Close();err!=nil{t.Fatal(err)};if mm.Used()!=0{t.Fatalf("leak=%d",mm.Used())}}
func TestHashAggregateCombineStatesMatchesSingle(t *testing.T){mm,scope,bm:=aggEnv(8<<20);specs:=[]Spec{{Kind:CountStar},{Kind:Sum,Input:1},{Kind:Avg,Input:1},{Kind:Min,Input:1},{Kind:Max,Input:1}};ts:=[]types.LogicalType{{ID:types.BigInt},{ID:types.BigInt}};all,_:=NewHashAggregate(scope,bm,ts,[]int{0},specs,8);left,_:=NewHashAggregate(scope,bm,ts,[]int{0},specs,4);right,_:=NewHashAggregate(scope,bm,ts,[]int{0},specs,4);c1:=makeBigIntChunk(t,scope,bm,[]int64{1,2,1},[]int64{10,20,30},nil);c2:=makeBigIntChunk(t,scope,bm,[]int64{2,1,3},[]int64{40,50,60},nil);_ = all.Consume(context.Background(),c1);_ = left.Consume(context.Background(),c1);c1.Release();_ = all.Consume(context.Background(),c2);_ = right.Consume(context.Background(),c2);c2.Release();if err:=left.CombineStates(context.Background(),right);err!=nil{t.Fatal(err)};aout,_:=all.Finalize(context.Background());lout,_:=left.Finalize(context.Background());encode:=func(c *vector.DataChunk)map[int64][5]float64{m:=map[int64][5]float64{};for i:=0;i<c.Cardinality;i++{g,_:=c.Columns[0].Int64(i);cnt,_:=c.Columns[1].Int64(i);s,_:=c.Columns[2].Int128(i);avg,_:=c.Columns[3].Float64(i);min,_:=c.Columns[4].Int64(i);max,_:=c.Columns[5].Int64(i);m[g]=[5]float64{float64(cnt),types.Int128ToFloat64(s),avg,float64(min),float64(max)}};return m};am,lm:=encode(aout),encode(lout);if len(am)!=len(lm){t.Fatal("group count mismatch")};for k,v:=range am{if lm[k]!=v{t.Fatalf("group %d mismatch",k)}};aout.Release();lout.Release();all.Release();left.Release();right.Release();if err:=scope.Close();err!=nil{t.Fatal(err)};if mm.Used()!=0{t.Fatalf("leak=%d",mm.Used())}}
func TestHashAggregateEmitMultipleChunks(t *testing.T){mm,scope,bm:=aggEnv(64<<20);a,err:=NewHashAggregate(scope,bm,[]types.LogicalType{{ID:types.BigInt}},[]int{0},[]Spec{{Kind:CountStar}},4096);if err!=nil{t.Fatal(err)};total:=vector.DefaultVectorSize+17;for base:=0;base<total;base+=vector.DefaultVectorSize{n:=total-base;if n>vector.DefaultVectorSize{n=vector.DefaultVectorSize};v,_:=vector.NewFlat(scope,bm,types.LogicalType{ID:types.BigInt},n);for i:=0;i<n;i++{v.SetInt64(i,int64(base+i))};c,_:=vector.NewDataChunk(v);if err:=a.Consume(context.Background(),c);err!=nil{t.Fatal(err)};c.Release()};rows,chunks:=0,0;if err:=a.Emit(context.Background(),func(c *vector.DataChunk)error{rows+=c.Cardinality;chunks++;c.Release();return nil});err!=nil{t.Fatal(err)};if rows!=total||chunks!=2{t.Fatalf("rows=%d chunks=%d",rows,chunks)};a.Release();if err:=scope.Close();err!=nil{t.Fatal(err)};if mm.Used()!=0{t.Fatalf("leak=%d",mm.Used())}}
func BenchmarkHashAggregateBigInt(b *testing.B){for i:=0;i<b.N;i++{mm,scope,bm:=aggEnv(64<<20);a,_:=NewHashAggregate(scope,bm,[]types.LogicalType{{ID:types.BigInt},{ID:types.BigInt}},[]int{0},[]Spec{{Kind:Sum,Input:1}},2048);c:=makeBigIntChunk(b,scope,bm,make([]int64,vector.DefaultVectorSize),make([]int64,vector.DefaultVectorSize),nil);for r:=0;r<vector.DefaultVectorSize;r++{c.Columns[0].SetInt64(r,int64(r%256));c.Columns[1].SetInt64(r,int64(r))};if err:=a.Consume(context.Background(),c);err!=nil{b.Fatal(err)};c.Release();out,err:=a.Finalize(context.Background());if err!=nil{b.Fatal(err)};out.Release();a.Release();if err:=scope.Close();err!=nil{b.Fatal(err)};if mm.Used()!=0{b.Fatal("leak")}}}
